def check(name,details=None):CHECKS.append({'check':name,'status':'passed','details':details})
def fingerprint(receipt):
    clone=dict(receipt);fp=clone.pop('query_fingerprint');assert hashlib.sha256(json.dumps(clone,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()==fp;return fp
