async def ready(page):await page.goto(URL);await expect(page.locator('#identity')).to_contain_text('Verified original CSV')
async def run(page,op='sum_source_usage_kwh',start='',end='',week='ALL',load='ALL',topic=''):
    await page.locator('#operation').select_option(op);await page.locator('#start').fill(start);await page.locator('#end').fill(end);await page.locator('#week').select_option(week);await page.locator('#load').select_option(load)
    if op=='report_missing_or_unresolved_field':await page.locator('#topic').select_option(topic)
    await page.locator('#confirm').check();await page.locator('#run').click();await expect(page.locator('#run')).to_be_enabled();await expect(page.locator('#result-state')).to_contain_text('EXECUTED')
