                browser=await p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox','--disable-gpu']);ctx=await browser.new_context(viewport={'width':1440,'height':1050},accept_downloads=True,timezone_id='UTC');page=await ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
