                await run(page,op='count_source_rows');await expect(page.locator('#energy-chart-panel')).to_be_hidden();assert 'kWh'not in await page.locator('#history .history-item').last.inner_text();assert 'filter_hash'not in await page.locator('#receipt-binding').inner_text();await expect(page.locator('#operation-answer')).to_contain_text('35040');check('Non-energy selected rows do not display empty energy chart or invent kWh history; policy digest named correctly')
                await run(page,op='report_missing_or_unresolved_field',topic='co2_mass');await expect(page.locator('#operation-answer')).to_contain_text('unit_and_derivation_unresolved');await expect(page.locator('#operation-answer')).to_contain_text('"value": null');await page.locator('#result-panel').evaluate("e=>e.scrollIntoView({block:'start'})");await page.screenshot(path=str(docs/'unresolved-desktop.png'));check('Carbon unit/derivation remains explicitly unresolved with no numeric answer')
