                check('Actual browser calendar/range/wholly outside/partial coverage stay distinct nonnumeric states');await page.locator('#result-panel').evaluate("e=>e.scrollIntoView({block:'start'})");await page.screenshot(path=str(docs/'partial-coverage-desktop.png'))
