                await run(page,start='2018-11-07',end='2018-11-08');zero=page.locator('#rows tr',has=page.locator('[data-row]')).last;await expect(zero).to_contain_text('csv-line-29857');await expect(zero).to_contain_text('07/11/2018 00:00');await zero.locator('button').click();await expect(page.locator('#source-row')).to_contain_text('"Usage_kWh": "0"');await expect(page.locator('#source-row')).to_contain_text('"usage_status": "valid"')
                await page.screenshot(path=str(docs/'stored-source-zero-desktop.png'));check('Stored source zero retains original raw label, row ID and valid numeric evidence; no physical-zero claim')
                # Hold a completed HTTP response while the user changes inputs and chooses later focus.
                gate=asyncio.Event();issued=asyncio.Event()
                async def delayed(route):response=await route.fetch();issued.set();await gate.wait();await route.fulfill(response=response)
                await page.route('**/api/query',delayed);await page.locator('#confirm').check();await page.locator('#run').click();await issued.wait();await page.locator('#start').fill('2018-01-15');await page.locator('#end').fill('2018-01-16');await page.locator('#end').focus();gate.set();await expect(page.locator('#result-state')).to_have_text('PREVIOUS EXECUTED QUERY');await expect(page.locator('#receipt')).to_be_disabled();await expect(page.locator('#end')).to_be_focused();await expect(page.locator('#executed-filter')).to_contain_text('2018-11-07');await page.unroute('**/api/query',delayed);check('Delayed executed response remains historical after input change and preserves later explicit focus')
