                assert titles[0]==titles[1]and '15/01/2018'in titles[0]and 'UTC'not in titles[0];check('Chart raw source-label tooltip is identical across browser timezones',titles[0])
                mobile=await browser.new_context(viewport={'width':390,'height':844},device_scale_factor=1);mp=await mobile.new_page();await ready(mp);await run(mp,start='2018-01-01',end='2018-02-01');dimensions=await mp.evaluate("({page:document.documentElement.scrollWidth,viewport:innerWidth,chart:document.querySelector('#chart').getBoundingClientRect().width,minText:Math.min(...Array.from(document.querySelectorAll('.metric span,pre,table,header span,label,footer')).filter(e=>e.offsetParent).map(e=>parseFloat(getComputedStyle(e).fontSize)))})");assert dimensions['page']<=390 and dimensions['chart']>=1200 and dimensions['minText']>=14;await mp.screenshot(path=str(docs/'energy-mobile-390.png'),full_page=True);check('390px layout has no page overflow, native Gantt-free chart scroll, meaningful text>=14px',dimensions);await mobile.close()
